def norm_ang(a):
    while a <= -180.0:
        a += 360.0
    while a > 180.0:
        a -= 360.0
    return a


def steer_toward(tx, ty, base_speed):
    b = bearing_to(tx, ty)
    ab = abs(b)
    if ab > 105.0:
        turn = max(-1.0, min(1.0, b / 42.0))
        return (-turn, turn)
    turn = max(-1.0, min(1.0, b / 36.0))
    fwd = base_speed * max(0.15, 1.0 - ab / 115.0)
    left = max(-1.0, min(1.0, fwd - turn))
    right = max(-1.0, min(1.0, fwd + turn))
    return (left, right)


def enemy_can_self_right(enemy):
    for sw in enemy.weapons.values():
        if sw["health"] > 0.0:
            wt = sw["type"]
            if wt == "hammer" or wt == "lifter":
                return True
            if wt == "flipper" and sw.get("shots_left", 0) > 0:
                return True
    return False


def drive(me, enemy, arena):
    mem = me.memory
    stuck = mem.get("stuck", 0)
    escape_until = mem.get("escape_until", 0.0)
    helpless = mem.get("helpless", 0)

    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = hypot(dx, dy)

    # Track if enemy is stranded in a knockout state so we do not knock them upright
    incap = enemy.on_side or (enemy.inverted and not enemy.invertible)
    if incap and not enemy.airborne and not enemy.righting:
        helpless += 1
    else:
        helpless = 0
    mem["helpless"] = helpless

    can_sr = enemy_can_self_right(enemy)
    if arena.time_left > 10.8 and ((not can_sr and helpless >= 3) or helpless >= 16):
        if dist < 1.65:
            b = bearing_to(enemy.x, enemy.y)
            turn = max(-0.4, min(0.4, b / 45.0))
            return (-0.55 - turn, -0.55 + turn)
        if dist > 2.4:
            return steer_toward(enemy.x, enemy.y, 0.35)
        b = bearing_to(enemy.x, enemy.y)
        if abs(b) > 12.0:
            turn = max(-0.5, min(0.5, b / 45.0))
            return (-turn, turn)
        return (0.0, 0.0)

    w = me.weapons.get("front")
    w_alive = w is not None and w["health"] > 0.0
    rpm = abs(w["rpm"]) if w_alive else 0.0

    # Check both front rotor corners against arena wall to protect wide spinner
    hr = radians(me.heading)
    ch = cos(hr)
    sh = sin(hr)
    c1x = me.x + ch * 0.72 - sh * 0.28
    c1y = me.y + sh * 0.72 + ch * 0.28
    c2x = me.x + ch * 0.72 + sh * 0.28
    c2y = me.y + sh * 0.72 - ch * 0.28
    nose_r = max(hypot(c1x, c1y), hypot(c2x, c2y))
    my_r = hypot(me.x, me.y)

    if w_alive and nose_r > arena.radius - 0.28 and nose_r > my_r + 0.12 and dist > 1.25:
        center_b = bearing_to(0.0, 0.0)
        turn = 0.85 if center_b >= 0.0 else -0.85
        return (-0.4 - turn, -0.4 + turn)

    # Detect unproductive clinch and briefly back out to re-bite
    if dist < 1.18 and abs(me.speed) < 0.22 and not enemy.airborne:
        stuck += 1
    else:
        stuck = max(0, stuck - 2)

    if stuck > 14 and arena.time > escape_until:
        escape_until = arena.time + 0.35
        stuck = 0

    mem["stuck"] = stuck
    mem["escape_until"] = escape_until

    if arena.time < escape_until:
        b = bearing_to(enemy.x, enemy.y)
        bias = 0.25 if b >= 0.0 else -0.25
        return (-0.85 + bias, -0.85 - bias)

    # Controlled opening advance so spinner reaches full lethal RPM before clash while scoring aggression
    if w_alive and rpm < 4700.0 and dist > 3.1 and arena.time < 2.2:
        eh = radians(enemy.heading)
        lx = enemy.x + cos(eh + pi / 2.0) * 1.1
        ly = enemy.y + sin(eh + pi / 2.0) * 1.1
        rx = enemy.x + cos(eh - pi / 2.0) * 1.1
        ry = enemy.y + sin(eh - pi / 2.0) * 1.1
        if hypot(lx, ly) <= hypot(rx, ry):
            return steer_toward(lx, ly, 0.30)
        return steer_toward(rx, ry, 0.30)

    # Flank enemy front weapon/wedge when approaching from ahead of them
    eh = radians(enemy.heading)
    to_me = degrees(atan2(me.y - enemy.y, me.x - enemy.x))
    rel_front = abs(norm_ang(to_me - enemy.heading))

    tx = enemy.x + enemy.vx * 0.12
    ty = enemy.y + enemy.vy * 0.12

    if rel_front < 58.0 and dist > 1.08:
        scale = 0.30 if w_alive else 0.45
        offset = min(0.72, max(0.28, dist * scale))
        s1x = tx + cos(eh + pi / 2.0) * offset
        s1y = ty + sin(eh + pi / 2.0) * offset
        s2x = tx + cos(eh - pi / 2.0) * offset
        s2y = ty + sin(eh - pi / 2.0) * offset
        d1 = hypot(s1x - me.x, s1y - me.y) + max(0.0, hypot(s1x, s1y) - 4.7) * 1.6
        d2 = hypot(s2x - me.x, s2y - me.y) + max(0.0, hypot(s2x, s2y) - 4.7) * 1.6
        if d1 <= d2:
            tx, ty = s1x, s1y
        else:
            tx, ty = s2x, s2y

    max_drv_temp = max(me.drive_left_temperature, me.drive_right_temperature)
    spd = 1.0
    if max_drv_temp > 125.0:
        spd = 0.72
    if me.battery_wh < 90.0:
        spd = min(spd, 0.65)

    # Controlled closing speed at top RPM for full 12mm single-tooth bite
    if w_alive and rpm > 5000.0 and dist < 1.15:
        spd = min(spd, 0.85)

    return steer_toward(tx, ty, spd)


def weapons(me, enemy, arena):
    w = me.weapons.get("front")
    if w is None or w["health"] <= 0.0:
        return None

    cur_rpm = w["rpm"]
    max_r = w["max_rpm"]

    # Keep fast spin direction so inverting never wastes energy braking through zero
    if abs(cur_rpm) > 1500.0:
        sign = 1.0 if cur_rpm >= 0.0 else -1.0
    else:
        sign = -1.0 if me.inverted else 1.0

    target = max_r

    # Ease RPM slightly on sharp close-range turns to raise gyro turn rate limit
    b = abs(bearing_to(enemy.x, enemy.y))
    dist = distance_to(enemy.x, enemy.y)
    if b > 60.0 and dist < 2.8:
        target = 4400.0

    temp = w["temperature"]
    if temp > 138.0:
        target = min(target, 3800.0)
    elif temp > 118.0:
        target = min(target, 5000.0)

    if me.battery_wh < 110.0:
        target = min(target, 4200.0)

    return [spin("front", sign * target)]

