    ew_dangerous = (
        ew is not None
        and ew["health"] > 0.0
        and ew["type"] == "spinner"
        and abs(ew.get("rpm", 0.0)) > 800.0
    )

    # Protect live front rotor from grazing the arena wall when not engaging close
    hr = radians(me.heading)
    ch = cos(hr)
    sh = sin(hr)
    c1x = me.x + ch * 0.56 - sh * 0.29
    c1y = me.y + sh * 0.56 + ch * 0.29
    c2x = me.x + ch * 0.56 + sh * 0.29
    c2y = me.y + sh * 0.56 - ch * 0.29
    nose_r = max(hypot(c1x, c1y), hypot(c2x, c2y))
    my_r = hypot(me.x, me.y)

    if w_alive and nose_r > arena.radius - 0.22 and nose_r > my_r + 0.12 and dist > 1.35:
