    if dist > 1.65 and abs(me.speed) < 0.12 and my_r > arena.radius - 0.85:
        wall_stuck += 1
    else:
        wall_stuck = max(0, wall_stuck - 2)
    mem["wall_stuck"] = wall_stuck

    if w_alive and dist < 1.05 and abs(me.speed) < 0.14 and rpm > 7100.0 and my_r < 5.1:
        stuck += 1
    else:
        stuck = max(0, stuck - 2)
    mem["stuck"] = stuck

    if (wall_stuck > 18 or stuck > 24) and arena.time > escape_until:
        escape_until = arena.time + 0.20
        mem["wall_stuck"] = 0
        mem["stuck"] = 0
    mem["escape_until"] = escape_until

