        if me.on_side and lw_ok and (not was_os or tick % 5 == 0):
            return [self_right()]
        if me.inverted and not w_ok and not ew_spin and lw_ok and distance_to(enemy.x, enemy.y) > 2.2 and arena.time_left > 15.0 and arena.time - mem.get("sr_t", -10.0) > 5.0:
            mem["sr_t"] = arena.time
            return [self_right()]

    if w_ok:
        cr = w["rpm"]
        sign = (1.0 if cr >= 0.0 else -1.0) if abs(cr) > 1200.0 else (-1.0 if me.inverted else 1.0)
        tgt = w["max_rpm"]
        tmp = w["temperature"]
        if tmp > 142.0:
            tgt = min(tgt, 5000.0)
        elif tmp > 124.0:
            tgt = min(tgt, 7400.0)
        if me.battery_wh < 90.0:
            tgt = min(tgt, 5500.0)
        cmds.append(spin("front", sign * tgt))

    if lw_ok and not me.airborne and not me.righting:
        if w_ok or me.inverted:
            if lw["state"] == "up" and not lw["engaged"]:
                cmds.append(lower("back"))
        elif not lw["engaged"]:
            if lw["state"] == "up":
                if arena.time - mem.get("lt", 0.0) > 0.35:
                    cmds.append(lower("back"))
            elif lw["cooldown"] <= 0.0 and not enemy.airborne and not enemy.righting:
                hr = radians(me.heading)
                dx, dy = enemy.x - me.x, enemy.y - me.y
                xl = dx * cos(hr) + dy * sin(hr)
                yl = -dx * sin(hr) + dy * cos(hr)
                if -0.97 <= xl <= -0.25 and abs(yl) <= 0.38:
                    mem["lt"] = arena.time
                    cmds.append(lift("back"))

    return cmds if cmds else None
